package com.portafolio.dt.controller;
import com.portafolio.dt.entity.Etapa; import com.portafolio.dt.repository.EtapaRepository; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/etapas") public class EtapaController {private final EtapaRepository repo;public EtapaController(EtapaRepository r){repo=r;}@GetMapping("/proyecto/{proyectoId}") public List<Etapa> proyecto(@PathVariable Long proyectoId){return repo.findByProyectoIdOrderById(proyectoId);}@GetMapping("/{id}") public ResponseEntity<Etapa> obtener(@PathVariable Long id){return repo.findById(id).map(ResponseEntity::ok).orElse(ResponseEntity.notFound().build());}@PutMapping("/{id}") public ResponseEntity<Etapa> actualizar(@PathVariable Long id,@RequestBody Etapa e){if(!repo.existsById(id))return ResponseEntity.notFound().build();e.setId(id);return ResponseEntity.ok(repo.save(e));}}
